import threading

counter = 0
lock = threading.Lock()

def add_unsafe():
    global counter
    for _ in range(100_000):
        counter += 1            # read, add, write: threads can interleave and lose updates

def add_safe():
    global counter
    for _ in range(100_000):
        with lock:              # only one thread in this block at a time
            counter += 1

